from __future__ import annotations

import base64
import gzip
import json
from functools import lru_cache

_OVERRIDES_B64 = """"""

@lru_cache(maxsize=1)
def overrides():
    raw = gzip.decompress(base64.b64decode(_OVERRIDES_B64))
    data = json.loads(raw.decode("utf-8"))
    if len(data) != 632:
        raise RuntimeError("Taxonomia V07 inválida: quantidade de correções divergente.")
    return data

def apply_taxonomy_v07(row):
    item = overrides().get(row.get("NumeroAnoOriginal"))
    if item:
        row["Categoria"] = item[0]
        row["Macroprocesso"] = item[1]
    return row
